import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './DMPage.css';

const DMPage = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // Fetch conversations
  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch('http://localhost:5001/api/conversations', {
          headers: { Authorization: `Bearer ${token}` }
        });
        const data = await res.json();
        setConversations(data.data);
        setLoading(false);
      } catch (err) {
        console.error('Error:', err);
        setLoading(false);
      }
    };
    fetchConversations();
  }, []);

  // Fetch messages when conversation is selected
  useEffect(() => {
    if (!selectedConversation) return;

    const fetchMessages = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch(
          `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const data = await res.json();
        setMessages(data.data);
      } catch (err) {
        console.error('Error:', err);
      }
    };
    fetchMessages();
  }, [selectedConversation]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    try {
      const token = localStorage.getItem('token');
      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`
          },
          body: JSON.stringify({ message: newMessage })
        }
      );
      const data = await res.json();
      setMessages([...messages, data.data]);
      setNewMessage('');
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleAcceptApplication = async () => {
    if (!selectedConversation) return;

    try {
      const token = localStorage.getItem('token');
      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/accept`,
        {
          method: 'PUT',
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      const data = await res.json();
      if (data.success) {
        alert('Application accepted successfully!');
        // Refresh messages to show the acceptance message
        const messagesRes = await fetch(
          `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const messagesData = await messagesRes.json();
        setMessages(messagesData.data);
      }
    } catch (err) {
      console.error('Error:', err);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="dm-container">
      {/* Left sidebar - Conversation list */}
      <div className="conversation-list">
        <h2>Conversations</h2>
        {conversations.length === 0 ? (
          <p>No conversations yet</p>
        ) : (
          <ul>
            {conversations.map((conv) => {
              const otherUser = conv.participants.find(
                p => p._id !== JSON.parse(localStorage.getItem('user'))._id
              );
              return (
                <li 
                  key={conv._id} 
                  className={selectedConversation?._id === conv._id ? 'active' : ''}
                  onClick={() => setSelectedConversation(conv)}
                >
                  <img 
                    src={otherUser.image || 'default-user.png'} 
                    alt={otherUser.name}
                  />
                  <div className="conversation-info">
                    <h3>{otherUser.name}</h3>
                    <p>{conv.lastMessage?.message?.substring(0, 30)}...</p>
                  </div>
                  {conv.isApplication && conv.status === 'pending' && (
                    <button 
                      className="accept-btn"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleAcceptApplication();
                      }}
                    >
                      Accept
                    </button>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {/* Right side - Chat area */}
      <div className="chat-area">
        {selectedConversation ? (
          <>
            <div className="chat-header">
              <h3>
                {selectedConversation.participants.find(
                  p => p._id !== JSON.parse(localStorage.getItem('user'))._id
                ).name}
              </h3>
            </div>
            <div className="messages-container">
              {messages.length === 0 ? (
                <p>No messages yet</p>
              ) : (
                messages.map((msg) => (
                  <div 
                    key={msg._id} 
                    className={`message ${msg.sender._id === JSON.parse(localStorage.getItem('user'))._id ? 'sent' : 'received'}`}
                  >
                    <p>{msg.message}</p>
                    <span className="timestamp">
                      {new Date(msg.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                ))
              )}
            </div>
            <div className="message-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div className="no-conversation">
            <p>Select a conversation to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DMPage;
